async function validateTargetDirectory(targetDir) {
  try {
    if (!existsSync20(targetDir)) {
      return { isValid: true };
    }
    const entries = await fs11.readdir(targetDir);
    if (entries.length > 0) {
      return {
        isValid: false,
        error: `Directory ${targetDir} already exists and is not empty. Please choose an empty directory or a new name.`
      };
    }
    return { isValid: true };
  } catch (error49) {
    return {
      isValid: false,
      error: `Failed to validate directory: ${error49 instanceof Error ? error49.message : "Unknown error"}`
    };
  }
}
