function parseSize(value, unit) {
  const num = parseFloat(value);
  const multipliers = {
    B: 1,
    KB: 1024,
    MB: 1024 * 1024,
    GB: 1024 * 1024 * 1024,
    TB: 1024 * 1024 * 1024 * 1024
  };
  return num * (multipliers[unit] || 1);
}
