function sanitizeProjectName(name) {
  if (!name || typeof name !== "string") {
    throw new Error("Project name is required and must be a string");
  }
  let sanitized = name.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/^@/, "").replace(/\//g, "-").replace(/[^a-z0-9-]/g, "-").replace(/^-+|-+$/g, "").replace(/-+/g, "-");
  const MAX_NAME_LENGTH = 50;
  if (sanitized.length > MAX_NAME_LENGTH) {
    sanitized = sanitized.substring(0, MAX_NAME_LENGTH);
    sanitized = sanitized.replace(/-+$/, "");
    logger28.warn({ src: "cli", command: "deploy-ecs", maxLength: MAX_NAME_LENGTH, truncated: sanitized }, "Project name truncated");
  }
  if (sanitized.startsWith("-")) {
    sanitized = sanitized.substring(1);
  }
  if (sanitized.length === 0) {
    throw new Error(`Project name '${name}' is invalid. Must contain at least one alphanumeric character.`);
  }
  if (!/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/.test(sanitized)) {
    throw new Error(`Sanitized project name '${sanitized}' failed final validation.`);
  }
  return sanitized;
}
function parseEnvironmentVariables(envOptions) {
  const environmentVars = {};
  if (!envOptions || envOptions.length === 0) {
    return environmentVars;
  }
  const MAX_ENV_VARS = 50;
  if (envOptions.length > MAX_ENV_VARS) {
    throw new Error(`Too many environment variables. Maximum ${MAX_ENV_VARS} allowed`);
  }
  for (let i = 0;i < envOptions.length; i++) {
    const envPair = envOptions[i];
    const equalIndex = envPair.indexOf("=");
    if (equalIndex === -1) {
      throw new Error(`Invalid environment variable format at position ${i + 1}: '${envPair}'. Expected KEY=VALUE`);
    }
    const key = envPair.substring(0, equalIndex);
    const value = envPair.substring(equalIndex + 1);
    if (!key || !/^[A-Za-z_][A-Za-z0-9_]*$/.test(key)) {
      throw new Error(`Invalid environment variable name at position ${i + 1}: '${key}'`);
    }
    if (value === "") {
      logger28.warn({ src: "cli", command: "deploy-ecs", envVar: key }, "Environment variable has an empty value");
    }
    environmentVars[key] = value;
  }
  return environmentVars;
}
async function getDetectedPlatform(platformOverride) {
  if (platformOverride) {
    return platformOverride;
  }
  if (process.env.ELIZA_DOCKER_PLATFORM) {
    return process.env.ELIZA_DOCKER_PLATFORM;
  }
  const arch = process.arch;
  if (arch === "arm64") {
    return "linux/arm64";
  } else if (arch === "x64") {
    return "linux/amd64";
  } else if (arch === "arm") {
    return "linux/arm/v7";
  }
  return "linux/amd64";
}
function getInstanceDefaults(architecture) {
  if (architecture === "arm64") {
    return {
      instanceType: "t4g.small",
      cpu: 1792,
      memory: 1792
    };
  } else {
    return {
      instanceType: "t3.small",
      cpu: 1792,
      memory: 1792
    };
  }
}

