function maskedValue(value) {
  if (!value)
    return "";
  if (value.length > 20 && !value.includes(" ")) {
    return `${value.substring(0, 4)}...${value.substring(value.length - 4)}`;
  }
  return value;
}

// src/commands/env/actions/edit.ts
async function editEnvVars(options, fromMainMenu = false) {
  const { yes } = options;
  const localEnvPath = await getLocalEnvPath();
  if (!localEnvPath || !existsSync29(localEnvPath)) {
    const exampleEnvPath = path32.join(process.cwd(), ".env.example");
    const hasExample = existsSync29(exampleEnvPath);
    if (hasExample) {
      console.log("No local .env file found. Create one with:");
      console.log("  cp .env.example .env");
    } else {
      console.log("No local .env file found in the current directory.");
      console.log("Create a .env file to set local environment variables.");
    }
    return fromMainMenu;
  }
  const envVars = await parseEnvFile(localEnvPath);
  if (Object.keys(envVars).length === 0) {
    console.log("Local .env file is empty.");
    const addNew = yes ? false : await ye({
      message: "Would you like to add a new environment variable?",
      initialValue: true
    });
    if (pD(addNew)) {
      xe("Operation cancelled.");
      process.exit(0);
    }
    if (addNew) {
      await addNewVariable(localEnvPath, envVars, yes);
    }
    return fromMainMenu;
  }
  let exit = false;
  let returnToMain = false;
  if (yes) {
    console.log("\u2705 Environment variables displayed. Use interactive mode without -y to edit.");
    return fromMainMenu;
  }
  while (!exit) {
    const entries = Object.entries(envVars);
    const choices = [
      ...entries.map(([key, value]) => ({
        title: `${key}: ${maskedValue(value)}`,
        value: key
      })),
      { title: "Add new variable", value: "add_new" },
      fromMainMenu ? { title: "Back to main menu", value: "back_to_main" } : { title: "Exit", value: "exit" }
    ];
    const selection2 = await ve({
      message: "Select a variable to edit or an action:",
      options: choices.map((choice) => ({
        value: choice.value,
        label: choice.title
      }))
    });
    if (pD(selection2)) {
      xe("Operation cancelled.");
      process.exit(0);
    }
    if (!selection2) {
      return fromMainMenu;
    }
    if (selection2 === "exit" || selection2 === "back_to_main") {
      exit = true;
      returnToMain = selection2 === "back_to_main";
      continue;
    }
    if (selection2 === "add_new") {
      await addNewVariable(localEnvPath, envVars, yes);
      continue;
    }
    const action = await ve({
      message: `What would you like to do with ${selection2}?`,
      options: [
        { label: "Edit", value: "edit" },
        { label: "Delete", value: "delete" },
        { label: "Back", value: "back" }
      ]
    });
    if (pD(action)) {
      xe("Operation cancelled.");
      process.exit(0);
    }
    if (!action || action === "back") {
      continue;
    }
    if (action === "edit") {
      const value = await he({
        message: `Enter the new value for ${selection2}:`,
        defaultValue: envVars[selection2]
      });
      if (pD(value)) {
        xe("Operation cancelled.");
        process.exit(0);
      }
      if (value !== undefined) {
        envVars[selection2] = value;
        await writeEnvFile2(localEnvPath, envVars);
        console.log(`\u2713 Updated ${selection2}`);
      }
    } else if (action === "delete") {
      let confirm = true;
      if (!yes) {
        const resp = await ye({
          message: `Are you sure you want to delete ${selection2}?`,
          initialValue: false
        });
        if (pD(resp)) {
          xe("Operation cancelled.");
          process.exit(0);
        }
        confirm = resp;
      }
      if (confirm) {
        delete envVars[selection2];
        await writeEnvFile2(localEnvPath, envVars);
        console.log(`\u2713 Removed ${selection2}`);
      }
    }
  }
  return returnToMain && fromMainMenu;
}
async function addNewVariable(envPath, envVars, yes = false) {
  if (yes) {
    console.log("Auto-confirmation mode enabled - skipping variable addition in edit-local -y mode");
    return;
  }
  const key = await he({
    message: "Enter the variable name:",
    validate: (value2) => value2.trim() !== "" ? undefined : "Variable name cannot be empty"
  });
  if (pD(key)) {
    xe("Operation cancelled.");
    process.exit(0);
  }
  if (!key)
    return;
  const value = await he({
    message: `Enter the value for ${key}:`,
    defaultValue: ""
  });
  if (pD(value)) {
    xe("Operation cancelled.");
    process.exit(0);
  }
  if (value !== undefined) {
    envVars[key] = value;
    await writeEnvFile2(envPath, envVars);
    console.log(`\u2713 Added ${key}`);
  }
}

