async function installPluginFromGitHub(plugin, cwd, opts) {
  const githubRegex = /^(?:github:)?([a-zA-Z0-9_-]+)\/([a-zA-Z0-9_.-]+)(?:#([a-zA-Z0-9_.-]+))?$/;
  const githubMatch = plugin.match(githubRegex);
  if (!githubMatch) {
    throw new Error("Invalid GitHub repository format");
  }
  const [, owner, repo, ref] = githubMatch;
  const githubSpecifier = `github:${owner}/${repo}${ref ? `#${ref}` : ""}`;
  const pluginNameForPostInstall = repo;
  const success3 = await installPlugin(githubSpecifier, cwd, undefined, opts.skipVerification);
  if (success3) {
    logger37.info({
      src: "cli",
      command: "plugins-install",
      plugin: pluginNameForPostInstall,
      source: githubSpecifier
    }, "Successfully installed plugin from GitHub");
    const packageName = extractPackageName(plugin);
    if (!opts.skipEnvPrompt) {
      await new Promise((resolve7) => setTimeout(resolve7, 500));
      console.log(`
\uD83D\uDD27 Checking environment variables for ${packageName}...`);
      try {
        await promptForPluginEnvVars(packageName, cwd);
      } catch (error49) {
        logger37.warn({
          src: "cli",
          command: "plugins-install",
          error: error49 instanceof Error ? error49.message : String(error49)
        }, "Could not prompt for environment variables");
      }
    } else {
      console.log(`
\u23ED\uFE0F  Skipping environment variable prompts due to --skip-env-prompt flag`);
    }
    showInstallationSuccess(packageName);
    process.exit(0);
  } else {
    logger37.error({ src: "cli", command: "plugins-install", source: githubSpecifier }, "Failed to install plugin from GitHub");
    process.exit(1);
  }
}
async function installPluginFromRegistry(plugin, cwd, opts) {
  const cachedRegistry = await fetchPluginRegistry();
  if (!cachedRegistry || !cachedRegistry.registry) {
    logger37.error({ src: "cli", command: "plugins-install" }, 'Plugin registry cache not found. Please run "elizaos plugins update" first');
    process.exit(1);
  }
  const possibleNames = normalizePluginName(plugin);
  const pluginKey = possibleNames.find((name) => cachedRegistry.registry[name]);
  const targetName = pluginKey || plugin;
  const registryInstallResult = await installPlugin(targetName, cwd, opts.tag, opts.skipVerification);
  if (registryInstallResult) {
    console.log(`Successfully installed ${targetName}`);
    const updatedDependencies = getDependenciesFromDirectory(cwd);
    const actualPackageName = findPluginPackageName(targetName, updatedDependencies || {}) || targetName;
    if (!opts.skipEnvPrompt) {
      await new Promise((resolve7) => setTimeout(resolve7, 500));
      console.log(`
\uD83D\uDD27 Checking environment variables for ${actualPackageName}...`);
      try {
        await promptForPluginEnvVars(actualPackageName, cwd);
      } catch (error49) {
        logger37.warn({
          src: "cli",
          command: "plugins-install",
          error: error49 instanceof Error ? error49.message : String(error49)
        }, "Could not prompt for environment variables");
      }
    } else {
      console.log(`
\u23ED\uFE0F  Skipping environment variable prompts due to --skip-env-prompt flag`);
    }
    showInstallationSuccess(actualPackageName);
    process.exit(0);
  }
  logger37.error({ src: "cli", command: "plugins-install", plugin: targetName }, "Failed to install plugin from registry");
  process.exit(1);
}
async function addPlugin(pluginArg, opts) {
  if (!pluginArg || !pluginArg.trim()) {
    logger37.error({ src: "cli", command: "plugins-install" }, "Plugin name cannot be empty or whitespace-only");
    logger37.info({ src: "cli", command: "plugins-install" }, 'Please provide a valid plugin name (e.g., "openai", "plugin-anthropic", "@elizaos/plugin-sql")');
    process.exit(1);
  }
  const cwd = process.cwd();
  const directoryInfo = detectDirectoryType(cwd);
  if (!directoryInfo || !directoryInfo.hasPackageJson) {
    logger37.error({ src: "cli", command: "plugins-install", directoryType: directoryInfo?.type || "invalid" }, "Command must be run inside an ElizaOS project directory");
    process.exit(1);
  }
  const allDependencies = getDependenciesFromDirectory(cwd);
  if (!allDependencies) {
    logger37.error({ src: "cli", command: "plugins-install" }, "Could not read dependencies from package.json");
    process.exit(1);
  }
  let plugin = pluginArg;
  const httpsGitHubUrlRegex = /^https?:\/\/github\.com\/([a-zA-Z0-9_-]+)\/([a-zA-Z0-9_.-]+?)(?:\.git)?(?:(?:#|\/tree\/|\/commit\/)([a-zA-Z0-9_.-]+))?\/?$/;
  const httpsMatch = plugin.match(httpsGitHubUrlRegex);
  if (httpsMatch) {
    const [, owner, repo, ref] = httpsMatch;
    plugin = `github:${owner}/${repo}${ref ? `#${ref}` : ""}`;
  }
  const installedPluginName = findPluginPackageName(plugin, allDependencies);
  if (installedPluginName) {
    logger37.info({ src: "cli", command: "plugins-install", plugin: installedPluginName }, "Plugin is already added to this project");
    process.exit(0);
  }
  const githubRegex = /^(?:github:)?([a-zA-Z0-9_-]+)\/([a-zA-Z0-9_.-]+)(?:#([a-zA-Z0-9_.-]+))?$/;
  if (githubRegex.test(plugin)) {
    await installPluginFromGitHub(plugin, cwd, opts);
  } else {
    await installPluginFromRegistry(plugin, cwd, opts);
  }
}

// src/commands/plugins/actions/remove.ts
init_directory_detection();
init_utils2();
init_bun_exec();
import { logger as logger38 } from "@elizaos/core";
import { existsSync as existsSync34, rmSync as rmSync3 } from "fs";
import path38 from "path";
async function removePlugin(plugin) {
  const cwd = process.cwd();
  const directoryInfo = detectDirectoryType(cwd);
  if (!directoryInfo || !directoryInfo.hasPackageJson) {
    console.error(`Could not read or parse package.json. This directory is: ${directoryInfo?.type || "invalid or inaccessible"}`);
    process.exit(1);
  }
  const allDependencies = getDependenciesFromDirectory(cwd);
  if (!allDependencies) {
    console.error("Could not read dependencies from package.json. Cannot determine which package to remove.");
    process.exit(1);
  }
  const packageNameToRemove = findPluginPackageName(plugin, allDependencies);
  if (!packageNameToRemove) {
    logger38.warn({ src: "cli", command: "plugins-remove", plugin }, "Plugin not found in project dependencies");
    console.info(`
Check installed plugins using: elizaos plugins installed-plugins`);
    process.exit(0);
  }
  console.info(`Removing ${packageNameToRemove}...`);
  try {
    await bunExecInherit("bun", ["remove", packageNameToRemove], {
      cwd
    });
  } catch (execError) {
    logger38.error({
      src: "cli",
      command: "plugins-remove",
      package: packageNameToRemove,
      error: execError instanceof Error ? execError.message : String(execError)
    }, "Failed to run bun remove");
    if (execError && typeof execError === "object" && "stderr" in execError && typeof execError.stderr === "string" && execError.stderr.includes("not found")) {
      logger38.info({ src: "cli", command: "plugins-remove" }, "bun remove indicated package was not found. Continuing with directory removal attempt");
    } else {
      handleError(execError);
      process.exit(1);
    }
  }
  let baseName = packageNameToRemove;
  if (packageNameToRemove.includes("/")) {
    const parts = packageNameToRemove.split("/");
    baseName = parts[parts.length - 1];
  }
  baseName = baseName.replace(/^plugin-/, "");
  const dirNameToRemove = `plugin-${baseName}`;
  const pluginDir = path38.join(cwd, dirNameToRemove);
  if (existsSync34(pluginDir)) {
    try {
      rmSync3(pluginDir, { recursive: true, force: true });
    } catch (rmError) {
      logger38.error({
        src: "cli",
        command: "plugins-remove",
        directory: pluginDir,
        error: rmError instanceof Error ? rmError.message : String(rmError)
      }, "Failed to remove directory");
    }
  } else {
    const nonPrefixedDir = path38.join(cwd, baseName);
    if (existsSync34(nonPrefixedDir)) {
      try {
        rmSync3(nonPrefixedDir, { recursive: true, force: true });
      } catch (rmError) {
        logger38.error({
          src: "cli",
          command: "plugins-remove",
          directory: nonPrefixedDir,
          error: rmError instanceof Error ? rmError.message : String(rmError)
        }, "Failed to remove directory");
      }
    }
  }
  console.log(`Successfully removed ${packageNameToRemove}`);
}

// src/commands/plugins/actions/list.ts
init_plugin_discovery();
init_utils2();
init_directory_detection();
import { logger as logger39 } from "@elizaos/core";
async function listAvailablePlugins(opts) {
  const cachedRegistry = await fetchPluginRegistry();
  if (!cachedRegistry || !cachedRegistry.registry || Object.keys(cachedRegistry.registry).length === 0) {
    logger39.info({ src: "cli", command: "plugins-list" }, "Plugin cache is empty or not found");
    console.log(`
Please run "elizaos plugins update" to fetch the latest plugin registry.`);
    return;
  }
  let availablePluginsToDisplay = [];
  const allPlugins = cachedRegistry ? Object.entries(cachedRegistry.registry) : [];
  let displayTitle = "Available v1.x plugins";
  if (opts.all) {
    displayTitle = "All plugins in local cache (detailed view)";
    if (allPlugins.length === 0) {
      console.log("No plugins found in the registry.");
    }
    allPlugins.forEach(([name, info2]) => {
      console.log(`
Plugin: ${name}`);
      const repoInfo = info2.git?.repo || info2.npm?.repo;
      console.log(`  Repository: ${repoInfo || "N/A"}`);
      console.log(`  v0 Compatible: ${info2.supports.v0 ? "Yes" : "No"}`);
      if (info2.npm?.v0 || info2.git?.v0?.version) {
        const ver = info2.npm?.v0 || info2.git?.v0?.version;
        const branch = info2.git?.v0?.branch;
        console.log(`    Version: ${ver || "N/A"}${branch ? ` (branch: ${branch})` : ""}`);
      }
      console.log(`  v1 Compatible: ${info2.supports.v1 ? "Yes" : "No"}`);
      if (info2.npm?.v1 || info2.git?.v1?.version) {
        const ver = info2.npm?.v1 || info2.git?.v1?.version;
        const branch = info2.git?.v1?.branch;
        console.log(`    Version: ${ver || "N/A"}${branch ? ` (branch: ${branch})` : ""}`);
      }
    });
    console.log("");
    return;
  } else if (opts.v0) {
    displayTitle = "Available v0.x plugins";
    availablePluginsToDisplay = allPlugins.filter(([, info2]) => info2.supports.v0).map(([name]) => name);
  } else {
    availablePluginsToDisplay = allPlugins.filter(([, info2]) => info2.supports.v1).map(([name]) => name);
  }
  logHeader(displayTitle);
  if (availablePluginsToDisplay.length === 0) {
    console.log("No plugins found matching the criteria in the registry.");
  } else {
    for (const pluginName of availablePluginsToDisplay) {
      console.log(`${pluginName}`);
    }
  }
  console.log("");
}
async function listInstalledPlugins() {
  const cwd = process.cwd();
  const directoryInfo = detectDirectoryType(cwd);
  if (!directoryInfo || !directoryInfo.hasPackageJson) {
    console.error(`Could not read or parse package.json. This directory is: ${directoryInfo?.type || "invalid or inaccessible"}`);
    console.info("Please run this command from the root of an ElizaOS project.");
    process.exit(1);
  }
  const allDependencies = getDependenciesFromDirectory(cwd);
  if (!allDependencies) {
    console.error("Could not read dependencies from package.json.");
    process.exit(1);
  }
  const pluginNames = Object.keys(allDependencies).filter((depName) => {
    return /^(@elizaos(-plugins)?\/)?plugin-.+/.test(depName);
  });
  if (pluginNames.length === 0) {
    console.log("No Eliza plugins found in the project dependencies (package.json).");
  } else {
    logHeader("Plugins Added:");
    for (const pluginName of pluginNames) {
      console.log(`${pluginName}`);
    }
    console.log("");
  }
}

// src/commands/plugins/index.ts
var plugins = new Command().name("plugins").description("Manage ElizaOS plugins").action(() => {
  plugins.help();
});
var pluginsCommand = plugins.command("list").aliases(["l", "ls"]).description("List available plugins to install into the project (shows v1.x plugins by default)").option("--all", "List all plugins from the registry with detailed version info").option("--v0", "List only v0.x compatible plugins").action(async (opts) => {
  try {
    await listAvailablePlugins(opts);
  } catch (error49) {
    handleError(error49);
  }
});
plugins.command("add").alias("install").description("Add a plugin to the project").argument("<plugin>", 'plugin name (e.g., "abc", "plugin-abc", "elizaos/plugin-abc")').option("-s, --skip-env-prompt", "Skip prompting for environment variables").option("--skip-verification", "Skip plugin import verification after installation").option("-b, --branch <branchName>", "Branch to install from when using monorepo source", "main").option("-T, --tag <tagname>", "Specify a tag to install (e.g., beta)").action(async (pluginArg, opts) => {
  try {
    await addPlugin(pluginArg, opts);
  } catch (error49) {
    handleError(error49);
  }
});
plugins.command("installed-plugins").description("List plugins found in the project dependencies").action(async () => {
  try {
    await listInstalledPlugins();
  } catch (error49) {
    if (error49 instanceof SyntaxError) {
      console.error(`Error parsing package.json: ${error49.message}`);
      process.exit(1);
    }
    handleError(error49);
    process.exit(1);
  }
});
plugins.command("remove").aliases(["delete", "del", "rm"]).description("Remove a plugin from the project").argument("<plugin>", 'plugins name (e.g., "abc", "plugin-abc", "elizaos/plugin-abc")').action(async (plugin, _opts) => {
  try {
    await removePlugin(plugin);
  } catch (error49) {
    handleError(error49);
    process.exit(1);
  }
});

