// src/commands/publish/actions/npm-publish.ts
init_bun_exec();
import { promises as fs18 } from "fs";
import path39 from "path";
async function publishToNpm2(cwd, packageJson, npmUsername) {
  console.info(`Publishing as npm user: ${npmUsername}`);
  if (!packageJson.npmPackage || packageJson.npmPackage === "${NPM_PACKAGE}") {
    if (!packageJson.name || packageJson.name.trim() === "") {
      throw new Error("Invalid package.json: name field is required for scoping");
    }
    if (packageJson.name.startsWith("@")) {
      throw new Error("Package name is already scoped - this should not happen with current templates");
    }
    if (!npmUsername || npmUsername.trim() === "") {
      throw new Error("npm username is required for package scoping");
    }
    const unscopedName = packageJson.name.startsWith("@") ? packageJson.name.split("/").slice(1).join("/") : packageJson.name;
    packageJson.npmPackage = `@${npmUsername}/${unscopedName}`;
    console.info(`Set npmPackage to: ${packageJson.npmPackage}`);
    const packageJsonPath = path39.join(cwd, "package.json");
    await fs18.writeFile(packageJsonPath, JSON.stringify(packageJson, null, 2), "utf-8");
  }
  console.info("Building package...");
  await bunExecInherit("npm", ["run", "build"], { cwd });
  console.info("Publishing to npm...");
  await bunExecInherit("npm", ["publish", "--ignore-scripts"], { cwd });
  console.log(`[\u221A] Successfully published ${packageJson.name}@${packageJson.version} to npm`);
}

// src/commands/publish/actions/github-publish.ts
init_utils2();
async function publishToGitHubAction(cwd, packageJson, credentials, skipRegistry = false, dryRun = false) {
  console.info("Publishing to GitHub and registry...");
  const result = await publishToGitHub(cwd, packageJson, credentials.username, skipRegistry, dryRun);
  if (!result) {
    throw new Error("GitHub publishing failed");
  }
  console.log(`[\u221A] Successfully published plugin ${packageJson.name}@${packageJson.version} to GitHub`);
  return result;
}

// src/commands/publish/actions/registry-publish.ts
import { promises as fs19 } from "fs";
import path40 from "path";
var REGISTRY_PACKAGES_PATH = "packages";
var LOCAL_REGISTRY_PATH = "packages/registry";
async function updateRegistryIndex(packageMetadata, dryRun = false) {
  try {
    const indexPath = dryRun ? path40.join(process.cwd(), LOCAL_REGISTRY_PATH, "index.json") : path40.join(process.cwd(), "temp-registry", "index.json");
    try {
      await fs19.access(path40.dirname(indexPath));
    } catch {
      await fs19.mkdir(path40.dirname(indexPath), { recursive: true });
      try {
        await fs19.access(indexPath);
      } catch {
        await fs19.writeFile(indexPath, JSON.stringify({
          v1: { packages: {} },
          v2: { packages: {} }
        }, null, 2));
      }
    }
    let indexContent;
    try {
      indexContent = await fs19.readFile(indexPath, "utf-8");
    } catch (error49) {
      indexContent = JSON.stringify({
        v1: { packages: {} },
        v2: { packages: {} }
      });
    }
    const index = JSON.parse(indexContent);
    if (!index.v2) {
      index.v2 = { packages: {} };
    }
    if (!index.v2.packages) {
      index.v2.packages = {};
    }
    if (!index.v2.packages[packageMetadata.name]) {
      index.v2.packages[packageMetadata.name] = {
        name: packageMetadata.name,
        description: packageMetadata.description,
        type: packageMetadata.type,
        versions: {}
      };
    }
    const packageInfo = index.v2.packages[packageMetadata.name];
    packageInfo.description = packageMetadata.description;
    packageInfo.type = packageMetadata.type;
    packageInfo.versions[packageMetadata.version] = {
      version: packageMetadata.version,
      runtimeVersion: packageMetadata.runtimeVersion,
      platform: packageMetadata.platform,
      publishedAt: packageMetadata.publishedAt,
      published: !dryRun
    };
    await fs19.writeFile(indexPath, JSON.stringify(index, null, 2));
    console.info(`Registry index ${dryRun ? "(dry run) " : ""}updated with ${packageMetadata.name}@${packageMetadata.version}`);
    return true;
  } catch (error49) {
    console.error(`Failed to update registry index: ${error49 instanceof Error ? error49.message : String(error49)}`);
    return false;
  }
}
async function savePackageToRegistry(packageMetadata, dryRun = false) {
  try {
    const packageDir = dryRun ? path40.join(process.cwd(), LOCAL_REGISTRY_PATH, REGISTRY_PACKAGES_PATH, packageMetadata.name) : path40.join(process.cwd(), "temp-registry", REGISTRY_PACKAGES_PATH, packageMetadata.name);
    const metadataPath = path40.join(packageDir, `${packageMetadata.version}.json`);
    await fs19.mkdir(packageDir, { recursive: true });
    await fs19.writeFile(metadataPath, JSON.stringify(packageMetadata, null, 2));
    console.info(`Package metadata ${dryRun ? "(dry run) " : ""}saved to ${metadataPath}`);
    await updateRegistryIndex(packageMetadata, dryRun);
    return true;
  } catch (error49) {
    console.error(`Failed to save package metadata: ${error49 instanceof Error ? error49.message : String(error49)}`);
    return false;
  }
}

// src/commands/publish/utils/validation.ts
