// src/commands/update/actions/cli-update.ts
async function performCliUpdate(options = {}) {
  try {
    const currentVersion = await getVersion2();
    const targetVersion = options.version || "latest";
    let latestVersion;
    if (targetVersion === "latest") {
      const outcome = await checkLatestCliVersionForChannel(currentVersion);
      if (outcome.status === "error") {
        console.warn("Could not check for CLI updates.");
        if (outcome.message) {
          logger41.debug({ error: outcome.message }, "CLI version check error");
        }
        return false;
      }
      if (outcome.status === "up_to_date") {
        console.log(`CLI is already at the latest version (${currentVersion}) [\u2713]`);
        return true;
      }
      latestVersion = outcome.version;
    } else {
      latestVersion = targetVersion;
    }
    const { needsUpdate } = checkVersionNeedsUpdate(currentVersion, latestVersion);
    if (!needsUpdate) {
      console.log(`CLI is already at the latest version (${currentVersion}) [\u2713]`);
      return true;
    }
    console.log(`Updating CLI from ${currentVersion} to ${latestVersion}...`);
    if (!options.skipBunMigration) {
      const npmInstallation = await isCliInstalledViaNpm();
      if (npmInstallation) {
        logger41.info("Detected npm installation, migrating to bun...");
        try {
          await migrateCliToBun(latestVersion);
          console.log(`CLI updated successfully to version ${latestVersion} [\u2713]`);
          return true;
        } catch (migrationError) {
          logger41.warn("Migration to bun failed, falling back to npm update...");
          logger41.debug("Migration error:", migrationError instanceof Error ? migrationError.message : String(migrationError));
          try {
            await bunExecInherit("npm", ["install", "-g", `@elizaos/cli@${latestVersion}`]);
            console.log(`CLI updated successfully to version ${latestVersion} [\u2713]`);
            return true;
          } catch (npmError) {
            throw new Error(`Both bun migration and npm fallback failed. Bun: ${migrationError instanceof Error ? migrationError.message : String(migrationError)}, npm: ${npmError instanceof Error ? npmError.message : String(npmError)}`);
          }
        }
      }
    }
    try {
      await bunExecInherit("bun", ["add", "-g", `@elizaos/cli@${latestVersion}`]);
      console.log(`CLI updated successfully to version ${latestVersion} [\u2713]`);
      return true;
    } catch (bunError) {
      console.error("Bun installation not found. Please install bun first:");
      console.error("  curl -fsSL https://bun.sh/install | bash");
      console.error("  # or");
      console.error("  npm install -g bun");
      logger41.debug({ error: bunError instanceof Error ? bunError.message : String(bunError) }, "Bun error:");
      return false;
    }
  } catch (error49) {
    console.error(`CLI update failed: ${error49 instanceof Error ? error49.message : String(error49)}`);
    return false;
  }
}

// src/commands/publish/utils/version-check.ts
async function checkCliVersion() {
  try {
    const cliPackageJsonPath = path42.resolve(path42.dirname(fileURLToPath5(import.meta.url)), "../package.json");
    const cliPackageJsonContent = await fs21.readFile(cliPackageJsonPath, "utf-8");
    const cliPackageJson = JSON.parse(cliPackageJsonContent);
    const currentVersion = cliPackageJson.version || "0.0.0";
    const latestVersion = await getLatestCliVersionForChannel(currentVersion);
    if (latestVersion && latestVersion !== currentVersion) {
      console.warn(`CLI update available: ${currentVersion} \u2192 ${latestVersion}`);
      const update = await ye({
        message: "Update CLI before publishing?",
        initialValue: false
      });
      if (pD(update)) {
        xe("Operation cancelled.");
        process.exit(0);
      }
      if (update) {
        console.info("Updating CLI...");
        try {
          await performCliUpdate();
          process.exit(0);
        } catch (updateError) {
          console.error("Failed to update CLI:", updateError);
        }
      }
    }
    return currentVersion;
  } catch (error49) {
    console.warn("Could not check for CLI updates");
    return "0.0.0";
  }
}

