function transformMatrixRunResultToScenarioRunResult(matrixResult) {
  let trajectory = [];
  let evaluations = [];
  let finalResponse = "";
  const scenarioResult = matrixResult.scenarioResult;
  if (scenarioResult && scenarioResult.executionResults) {
    const firstExecutionResult = scenarioResult.executionResults[0];
    if (firstExecutionResult) {
      if (firstExecutionResult.trajectory) {
        trajectory = firstExecutionResult.trajectory.map((step) => {
          const stepType = step.type === "action" || step.type === "thought" || step.type === "observation" ? step.type : "observation";
          return {
            type: stepType,
            timestamp: step.timestamp,
            content: typeof step.content === "string" ? step.content : String(step.content || "")
          };
        });
      }
      finalResponse = firstExecutionResult.stdout || "";
    }
  }
  const scenarioResultWithEvaluations = scenarioResult;
  if (scenarioResultWithEvaluations && scenarioResultWithEvaluations.evaluations) {
    const filteredEvaluations = scenarioResultWithEvaluations.evaluations.filter((evaluation) => {
      return evaluation && typeof evaluation.evaluator_type === "string" && typeof evaluation.success === "boolean" && typeof evaluation.summary === "string" && evaluation.details !== undefined && typeof evaluation.details === "object" && evaluation.details !== null;
    });
    evaluations = filteredEvaluations.map((evaluation) => ({
      evaluator_type: evaluation.evaluator_type,
      success: evaluation.success,
      summary: evaluation.summary,
      details: evaluation.details
    }));
  }
  let llmCallCount = 0;
  if (trajectory.length > 0) {
    llmCallCount = trajectory.filter((step) => step.type === "thought" || step.type === "action" && typeof step.content === "object" && step.content.name === "REPLY" || step.type === "observation" && typeof step.content === "string" && step.content.includes("Generated reply:")).length;
    if (llmCallCount === 0 && trajectory.length > 0) {
      llmCallCount = 1;
    }
  }
  const baseMetrics = matrixResult.metrics || { memoryUsage: 0, diskUsage: 0, tokenCount: 0 };
  const transformedMetrics = {
    execution_time_seconds: matrixResult.duration / 1000,
    llm_calls: llmCallCount,
    total_tokens: baseMetrics.tokenCount || 0,
    ...Object.fromEntries(Object.entries(baseMetrics).filter(([key, value]) => !["tokenCount", "memoryUsage", "diskUsage", "cpuUsage"].includes(key) && typeof value === "number"))
  };
  return {
    run_id: matrixResult.runId,
    matrix_combination_id: matrixResult.combinationId,
    parameters: matrixResult.parameters,
    metrics: transformedMetrics,
    final_agent_response: finalResponse,
    evaluations,
    trajectory,
    error: matrixResult.error || null
  };
}
