async function runTypeCheck(projectPath, strict = true) {
  const tsconfigPath = path62.join(projectPath, "tsconfig.json");
  if (!existsSync41(tsconfigPath)) {
    return {
      success: false,
      errors: [`No tsconfig.json found at ${tsconfigPath}`],
      warnings: []
    };
  }
  try {
    const args = ["--noEmit"];
    if (strict) {
      args.push("--strict");
    }
    const result = await bunExec("bun", ["x", "tsc", ...args], {
      cwd: projectPath
    });
    const { stdout, stderr } = result;
    const hasErrors = stderr.includes("error TS") || stdout.includes("error TS");
    return {
      success: !hasErrors,
      errors: hasErrors ? [stderr || stdout] : [],
      warnings: stderr.includes("warning") ? [stderr] : []
    };
  } catch (error49) {
    const errorMessage = error49 instanceof Error ? error49.message : String(error49);
    logger48.error({ error: errorMessage }, "TypeScript validation failed:");
    return {
      success: false,
      errors: [`TypeScript validation error: ${errorMessage}`],
      warnings: []
    };
  }
}

