async function runComponentTests(testPath, options, projectInfo) {
  const cwd = process.cwd();
  const isPlugin2 = projectInfo.type === "elizaos-plugin";
  if (!options.skipTypeCheck) {
    logger49.info({ src: "cli", command: "test-component" }, "Running TypeScript validation");
    const typeCheckResult = await runTypeCheck(cwd, true);
    if (!typeCheckResult.success) {
      logger49.error({ src: "cli", command: "test-component" }, "TypeScript validation failed");
      typeCheckResult.errors.forEach((error49) => logger49.error({ src: "cli", command: "test-component", error: error49 }, "Type error"));
      return { failed: true };
    }
    logger49.success({ src: "cli", command: "test-component" }, "TypeScript validation passed");
  }
  if (!options.skipBuild) {
    try {
      logger49.info({ src: "cli", command: "test-component", isPlugin: isPlugin2 }, "Building project");
      await buildProject(cwd, isPlugin2);
      logger49.success({ src: "cli", command: "test-component" }, "Build completed successfully");
    } catch (buildError) {
      logger49.error({
        src: "cli",
        command: "test-component",
        error: buildError instanceof Error ? buildError.message : String(buildError)
      }, "Build failed");
      return { failed: true };
    }
  }
  logger49.info({ src: "cli", command: "test-component" }, "Running component tests");
  const args = ["test", "--passWithNoTests"];
  if (options.name) {
    const baseName = processFilterName(options.name);
    if (baseName) {
      logger49.info({ src: "cli", command: "test-component", filter: baseName }, "Using test filter");
      args.push("-t", baseName);
    }
  }
  const monorepoRoot = UserEnvironment.getInstance().findMonorepoRoot(process.cwd());
  const baseDir = monorepoRoot ?? process.cwd();
  const targetPath = testPath ? path63.resolve(baseDir, testPath) : process.cwd();
  logger49.info({ src: "cli", command: "test-component", execCommand: `bun ${args.join(" ")}`, targetPath }, "Executing test command");
  try {
    const result = await bunExecInherit("bun", args, {
      cwd: targetPath,
      env: {
        FORCE_COLOR: "1",
        CI: ""
      }
    });
    logger49.info({ src: "cli", command: "test-component" }, "Component tests completed");
    return { failed: !result.success };
  } catch (error49) {
    logger49.error({
      src: "cli",
      command: "test-component",
      error: error49 instanceof Error ? error49.message : String(error49)
    }, "Error running component tests");
    return { failed: true };
  }
}

